    42|/** Bounded loop: max LLM revision iterations before BLOCKED. */
    43|const MAX_ITERATIONS = 6;
    44|/** Per-command timeout (ms). */
    45|const COMMAND_TIMEOUT_MS = 60_000;
    46|/** LLM planning timeout (ms). The Render runtime was hanging in the planning
    47| * phase indefinitely; this hard cap ensures the loop progresses or BLOCKS with
    48| * a real reason instead of sitting at RUNNING 10% forever. */
    49|const LLM_TIMEOUT_MS = 90_000;
    50|/** LLM planning attempts before LLM_PLAN_INVALID BLOCKED. */
    51|const MAX_LLM_ATTEMPTS = 4;
    52|/** Stage-specific timeouts (ms) — each bounded loop stage has its own hard cap
    53| * so a stuck inspection / patch / test / commit / deploy is detectable and the
    54| * engine BLOCKS with a real reason instead of hanging forever. These are
    55| * checked between stages via the wall-clock elapsed-since-stage-start timer. */
    56|const STAGE_TIMEOUTS_MS: Record<string, number> = {
    57|  inspecting: 30_000,
    58|  planning: LLM_TIMEOUT_MS + 5_000,
    59|  patching: 120_000,
