   755|function withTimeoutAndAbort<T>(
   756|  promise: Promise<T>,
   757|  ms: number,
   758|  label: string,
   759|  abortController?: AbortController,
   760|): Promise<T> {
   761|  return Promise.race([
   762|    promise,
